import { test, expect } from '@playwright/test';

/** A role credential from the environment; fails clearly when it is not set. */
function credential(name: string, value: string | undefined): string {
  if (!value) throw new Error(`Environment variable ${name} is not set`);
  return value;
}

test('SCN-0003: Prevent login with the standard username and a wrong password', async ({ page }) => {
  // Expected (REQ-001): Wrong password: logging in with the standard user's username and the password wrong_password is prevented and the message Epic sadface: Username and password do not match any user in this service is shown.
  await page.goto('/');
  await page.getByRole('textbox', { name: 'Username', exact: true }).fill(credential('SAUCEDEMO_STANDARD_USER_USERNAME', process.env.SAUCEDEMO_STANDARD_USER_USERNAME));
  await page.getByRole('textbox', { name: 'Password', exact: true }).fill('wrong_password');
  await page.getByRole('button', { name: 'Login', exact: true }).click();
  await expect(page.getByText('Epic sadface: Username and password do not match any user in this service', { exact: true })).toBeVisible();
});
